/* PageHeader与DataTable：共享组件增强，不生成业务页面。 */
window.EamUiComponents=(()=>{
 const toolIcons={refresh:'M20 7v5h-5 M4 17v-5h5 M19 12a7 7 0 0 0-12-5 M5 12a7 7 0 0 0 12 5',export:'M12 3v12 M7 10l5 5 5-5 M5 16v5h14v-5',import:'M12 16V4 M7 9l5-5 5 5 M5 16v5h14v-5',columns:'M4 4h16v16H4z M9 4v16 M15 4v16',filter:'M3 5h18 M6 12h12 M10 19h4'};
 function pageHeader(){const main=document.querySelector('main');let title=main?.querySelector(':scope>.title,:scope>.archive-pagehead'),crumb=document.getElementById('breadcrumb');if(!title&&main?.querySelector(':scope>h1')){title=document.createElement('div');title.className='title';const identity=document.createElement('div');identity.append(main.querySelector(':scope>h1'));title.append(identity);main.prepend(title);}if(!crumb&&title){crumb=document.createElement('div');crumb.id='breadcrumb';crumb.textContent='系统平台 / 设备管理 / '+document.title.split('·')[0].trim();}if(!title||!crumb)return;
 for(const button of title.querySelectorAll('button,a'))if(/^[←↩\s]*(返回台账|返回平台|返回列表|返回工作台)$/.test(button.textContent.trim()))button.remove();
 title.dataset.component='page-header';title.classList.add('eam-page-header');
 const identity=title.querySelector(':scope>div:first-child');if(identity)identity.classList.add('page-header-identity');
 const nav=document.createElement('nav');nav.className='page-header-breadcrumb';nav.setAttribute('aria-label','面包屑导航');const segments=[];let current=document.body.dataset.page;const query=new URLSearchParams(location.search),seen=new Set();while(current&&!seen.has(current)){seen.add(current);const route=EamPageRoutes[current]||{label:document.title.split('·')[0].trim(),parent:'workbench'};segments.unshift({page:current,label:current==='inspection'&&query.get('tab')==='special'?'专项检查执行':route.label});current=current==='inspection'&&query.get('tab')==='special'?'check-list':route.parent;}const list=document.createElement('ol');list.className='breadcrumb mb-0';
 segments.forEach((segment,index)=>{const item=document.createElement('li');item.className='breadcrumb-item';if(index===segments.length-1){item.textContent=segment.label;item.setAttribute('aria-current','page');}else{const link=document.createElement('a');link.textContent=segment.label;link.href=segment.page+'.html?view='+(document.body.classList.contains('mobile-preview')?'mobile':'pc');item.append(link);}list.append(item);});crumb.replaceChildren(list);crumb.className='';nav.append(crumb);title.append(nav);
 const actions=title.querySelector(':scope>.actions,:scope>.d-flex');if(actions){if(!actions.children.length)actions.remove();else{actions.classList.add('page-header-actions');title.after(actions);}} }
 const statuses=new WeakMap();
 const stateCopy={empty:['暂无数据','请调整筛选条件或刷新列表。'],loading:['正在加载','请稍候。'],error:['数据加载失败','请重试。']};
 function syncTableState(table){
  if(!table)return;const state=statusFor(table),body=table.tBodies[0]||table.createTBody(),records=[...body.rows].filter(row=>!row.hasAttribute('data-table-state'));
  const scope=table.closest('section')||table.parentElement.parentElement;for(const legacy of scope.querySelectorAll('#list-empty,#master-empty,#empty-search,#empty-state,#work-empty,#hazard-empty,#review-queue-empty,#review-queue-empty')){legacy.hidden=true;legacy.dataset.component='legacy-empty-placeholder';}
  const mode=['loading','error'].includes(state.mode)?state.mode:records.length?'loaded':'empty';let row=body.querySelector(':scope>[data-table-state]');
  if(records.length){if(row)row.remove();}else{
   const columns=Math.max(1,[...(table.tHead?.rows[0]?.cells||[])].filter(cell=>!cell.hidden).reduce((sum,cell)=>sum+cell.colSpan,0)),copy=stateCopy[mode]||stateCopy.empty,key=mode+'|'+columns+'|'+copy.join('|');
   if(!row){row=document.createElement('tr');row.dataset.tableState=mode;body.append(row);}if(row.dataset.stateKey!==key){row.replaceChildren();row.dataset.stateKey=key;row.dataset.tableState=mode;const cell=document.createElement('td');cell.colSpan=columns;cell.className='text-center text-secondary py-5';const box=document.createElement('div');box.dataset.component='table-state';box.className='d-flex flex-column align-items-center gap-2';const title=document.createElement('strong'),hint=document.createElement('span');title.textContent=copy[0];hint.textContent=copy[1];box.append(title,hint);cell.append(box);row.append(cell);}
  }
  if(!['loading','error'].includes(state.mode)){const text=records.length?'已展示 · 当前页'+records.length+'条':'暂无数据';if(state.host.textContent!==text)state.host.textContent=text;state.host.dataset.state=mode;}
 }
 function statusFor(table){let state=statuses.get(table);if(state)return state;const wrapper=table.parentElement;let host=wrapper.previousElementSibling;if(!host?.matches('[role=status]')){host=document.createElement('div');wrapper.before(host);}host.classList.add('load-status');host.dataset.component='load-status';host.setAttribute('role','status');host.setAttribute('aria-live','polite');state={host,mode:'auto',last:''};statuses.set(table,state);return state;}
 function setTableStatus(target,mode,message,retry){const table=typeof target==='string'?document.getElementById(target)?.closest('table'):target;if(!table)return;const state=statusFor(table);state.mode=mode;table.setAttribute('aria-busy',String(mode==='loading'));const text=message||({loading:'正在读取…',empty:'暂无数据',error:'读取失败，请重试',loaded:'已加载'}[mode]||'');if(state.host.textContent!==text||mode==='error'){state.host.replaceChildren();const label=document.createElement('span');label.textContent=text;state.host.append(label);if(mode==='error'&&retry){const button=document.createElement('button');button.type='button';button.className='btn btn-sm btn-outline-secondary';button.textContent='重试';button.onclick=retry;state.host.append(button);}}state.host.dataset.state=mode;syncTableState(table);}
 function decorateTables(){
for(const link of document.querySelectorAll('table .row-link,table .work-link')){link.classList.add('d-flex','flex-column','align-items-start','text-decoration-none');link.style.maxWidth='240px';for(const child of link.children){child.classList.add('d-block','text-truncate');child.style.maxWidth='240px';child.title=child.textContent;}}for(const cell of document.querySelectorAll('table tbody tr>td:last-child')){const buttons=[...cell.children].filter(e=>e.tagName==='BUTTON');if(!buttons.length)continue;cell.classList.add('row-actions');if(buttons.length>2&&!cell.querySelector('details')){const more=document.createElement('details');more.className='row-more';const summary=document.createElement('summary');summary.className='btn btn-outline-secondary';summary.textContent='更多';const menu=document.createElement('div');menu.className='row-action-menu';for(const b of buttons.slice(2))menu.append(b);more.append(summary,menu);cell.append(more);}}for(const table of document.querySelectorAll('table')){table.classList.remove('data-table','ledger-table','archive-record-table','work-outcomes');table.classList.add('table','table-hover','align-middle','mb-0');delete table.dataset.freezeFirst;table.parentElement.classList.add('table-responsive');if(table.tHead)table.tHead.classList.add('sticky-top','table-light');for(const th of table.querySelectorAll('th')){th.classList.add('px-3','py-2','text-nowrap','fw-semibold');th.scope='col';}for(const td of table.querySelectorAll('tbody td')){if(td.closest('[data-table-state]'))continue;td.classList.add('px-3','py-3','text-nowrap');for(const child of td.children){if(child.matches('input,select,textarea,button,details,.table-actions,.badge'))continue;if(child.matches('small,strong,b,span,p,div')&&!child.querySelector('input,select,textarea,button,details')){child.classList.add('d-block','text-truncate');child.style.maxWidth=td.cellIndex===0?'240px':'200px';child.title=child.textContent;}}if(td.classList.contains('row-actions')&&!td.querySelector(':scope>.table-actions')){const group=document.createElement('div');group.className='table-actions d-flex align-items-center flex-nowrap gap-1';while(td.firstChild)group.append(td.firstChild);td.append(group);}}table.parentElement.tabIndex=0;table.parentElement.setAttribute('aria-label','业务表格，可横向滚动');}
 for(const table of document.querySelectorAll('table')){table.dataset.component='data-table';table.classList.add('eam-data-table');const state=statusFor(table);syncTableState(table);
 for(const cell of table.querySelectorAll('tbody tr>td:last-child'))for(const b of cell.querySelectorAll('button,summary')){if(b.matches('.row-link,.work-link'))continue;b.classList.add('btn','btn-sm','text-nowrap');for(const name of [...b.classList])if(name.startsWith('btn-')&&!['btn-sm','btn-danger'].includes(name))b.classList.remove(name);if(!b.classList.contains('btn-danger'))b.classList.add('btn-outline-secondary');b.classList.remove('p-0','py-0','px-0');b.classList.add('table-action-button');}
 }
 }
 function filterBar(input){const group=document.createElement('div');group.className='input-group input-group-sm list-search-group';group.dataset.component='filter-bar';input.classList.add('form-control');group.append(input);return group;}
 const paginationText=(total,page,pages)=>'共 '+total+' 条 · 第 '+page+' / '+pages+' 页';
 function pagination(host,{page,pages,total,pageSize,onChange,previousId,nextId,countId}){if(!host)return;if(host.hasAttribute('data-component-src')){host=host.querySelector('[data-region=body]');if(!host)return;}const ids=new Map([...host.querySelectorAll('[id]')].map(el=>[el.dataset.localId||el.id,el.id]));const scopedId=id=>ids.get(id)||(host.closest('[data-instance]')?.dataset.instance?host.closest('[data-instance]').dataset.instance+'-'+id:id);host.className='list-pagination';host.dataset.component='pagination';host.replaceChildren();const info=document.createElement('span');if(countId){info.id=scopedId(countId);info.dataset.localId=countId;}info.textContent=paginationText(total,page,pages);const controls=document.createElement('div');for(const [label,delta]of [['上一页',-1],['下一页',1]]){const button=document.createElement('button');button.type='button';button.className='btn btn-sm btn-outline-secondary';button.textContent=label;if(delta<0&&previousId){button.id=scopedId(previousId);button.dataset.localId=previousId;}if(delta>0&&nextId){button.id=scopedId(nextId);button.dataset.localId=nextId;}button.disabled=delta<0?page===1:page===pages;button.onclick=()=>onChange(page+delta);controls.append(button);}host.append(info,controls);}
 function openFilter(panel,trigger){
  const controls=[...panel.querySelectorAll('input,select,textarea')],snapshot=controls.map(control=>({control,value:control.value,checked:control.checked}));
  const anchor=document.createComment('筛选表单原位置');panel.before(anchor);const dialog=document.createElement('dialog');dialog.dataset.component='advanced-filter';dialog.className='filter-dialog';dialog.setAttribute('aria-label','高级筛选');const title=document.createElement('h2');title.textContent='高级筛选';title.className='h5';const footer=document.createElement('div');footer.className='d-flex justify-content-end gap-2 mt-3';let applied=false;
  for(const [name,primary]of [['取消',false],['应用筛选',true]]){const button=document.createElement('button');button.type='button';button.className='btn btn-sm '+(primary?'btn-primary':'btn-outline-secondary');button.textContent=name;button.onclick=()=>{applied=primary;dialog.close();};footer.append(button);}
  panel.hidden=false;dialog.append(title,panel,footer);document.body.append(dialog);
  for(const select of panel.querySelectorAll('select'))if(!select.closest('label')&&!select.parentElement.classList.contains('input-group')){const group=document.createElement('div');group.className='input-group input-group-sm';const label=document.createElement('span');label.className='input-group-text';label.textContent=select.getAttribute('aria-label')||'业务状态';select.before(group);group.append(label,select);}
  dialog.addEventListener('change',event=>event.stopImmediatePropagation(),true);dialog.addEventListener('input',event=>event.stopImmediatePropagation(),true);
  panel.addEventListener('click',reset,true);
  function reset(event){const button=event.target.closest('button');if(!button)return;event.stopImmediatePropagation();event.preventDefault();for(const control of controls){control.value='';control.checked=false;}}
  dialog.addEventListener('close',()=>{panel.removeEventListener('click',reset,true);if(!applied)for(const item of snapshot){item.control.value=item.value;item.control.checked=item.checked;}anchor.replaceWith(panel);panel.hidden=true;dialog.remove();trigger?.setAttribute('aria-expanded','false');if(applied)for(const control of controls)control.dispatchEvent(new Event(control.tagName==='INPUT'&&control.type!=='checkbox'?'input':'change',{bubbles:true}));trigger?.focus();},{once:true});trigger?.setAttribute('aria-expanded','true');dialog.showModal();
 }
 function decoratePagination(){for(const host of document.querySelectorAll('.list-pagination')){host.dataset.component='pagination';for(const button of host.querySelectorAll('button'))button.classList.add('btn','btn-sm','btn-outline-secondary');}for(const host of document.querySelectorAll('[data-component="filter-bar"]')){for(const label of host.querySelectorAll(':scope>.input-group-text'))if(['关键词','关键字'].includes(label.textContent.trim()))label.remove();}for(const button of document.querySelectorAll('[data-filter-toggle],#open-advanced-filter,[data-component="advanced-filter-trigger"]')){button.dataset.component='advanced-filter-trigger';toolIcon(button,'filter','高级筛选');}}

 function columnVisibility(table,indices){for(const row of table.rows)for(const cell of row.cells)if(!row.hasAttribute('data-table-state'))cell.hidden=indices.includes(cell.cellIndex);syncTableState(table);}
 function toolIcon(button,key,label){if(button.dataset.toolIcon===key&&button.querySelector('svg')&&button.title===label)return;button.dataset.toolIcon=key;const badge=button.querySelector('#filter-badge');button.replaceChildren();const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',toolIcons[key]);svg.append(path);button.append(svg);if(badge)button.append(badge);button.classList.add('list-icon-button');button.title=label;button.setAttribute('aria-label',label);}
 return {columnVisibility,toolIcon,decorateTables,setTableStatus,syncTableState,filterBar,pagination,paginationText,decoratePagination,openFilter,pageHeader};
})();
